mkdir_cd() {
    case "${1-}" in
        -h | --help | "")
            __gash_call mkdir_cd "$@"
            return
            ;;
    esac
    # One directory only: a second word is the binary's "Unexpected
    # argument" (LEDGER SYS-10).
    if (($# > 1)); then
        __gash_call mkdir_cd "$@"
        return
    fi
    # No option parsing, no CDPATH, and "-" is ./- (LEDGER SYS-11).
    local dir="$1"
    [[ "$dir" == - ]] && dir=./-
    mkdir -p -- "$dir" && CDPATH='' cd -- "$dir" || return 1
}
